    """Greedy max-work spanning arborescence rooted at root (or None)."""
    placed = set([root])
    parents = {}
    while len(placed) < len(C):
        best = None
        for w in C:
            if w in placed:
                continue
            for u in placed:
                val = work.get((u, w), 0)
                if val > 0 and (best is None or val > best[0]):
                    best = (val, u, w)
        if best is None:
            return None
        _val, u, w = best
        parents[w] = u
        placed.add(w)
    return parents


def _decompose_trees(root, total, lv, parts):
    """Split the pair-demand dict lv into arborescence records for `root`."""
    C = [v for (v, _rv) in parts]
    work = {}
    for k, val in lv.items():
        if val > 0:
            work[k] = val
    budget = [4000]

    def rec(wrk, left):
        if left <= 0:
            return [] if not any(wrk.values()) else None
        if budget[0] <= 0:
            return None
        budget[0] -= 1
        parents = _find_arborescence(root, wrk, C)
        if parents is None:
            return None
        edges = [[parents[w], w] for w in parents]
        cmax = min([wrk[(parents[w], w)] for w in parents] + [left])
        # upper bound from the connectivity invariant on unions of subtrees
        limit = cmax
        for w in parents:
            # subtree below w (in this tree)
            sub = set([w])
            changed = True
            while changed:
                changed = False
                for x in parents:
                    if parents[x] in sub and x not in sub:
                        sub.add(x)
                        changed = True
            k = len([1 for x in sub if parents.get(x) is not None
                     and parents[x] not in sub])
            enter = 0
            for x in sub:
                for u in C:
                    if u not in sub:
                        enter += wrk.get((u, x), 0)
            if k > 1:
                limit = min(limit, (enter - left) // (k - 1))
        if limit < 1:
            limit = 1
        cands = [limit]
        for d in range(1, 6):
            if limit - d >= 1:
                cands.append(limit - d)
        for cnt in cands:
            if cnt > cmax:
                continue
            nwrk = dict(wrk)
            ok = True
            for w in parents:
                key = (parents[w], w)
                nwrk[key] = nwrk.get(key, 0) - cnt
                if nwrk[key] < 0:
                    ok = False
                    break
            if not ok:
                continue
            rest = rec({k: v for k, v in nwrk.items() if v > 0}, left - cnt)
            if rest is not None:
                return [[root, cnt, edges]] + rest
        return None

    out = rec(work, total)
    if out is None:
        return None
    if sum(rec[1] for rec in out) != total:
        return None
    if len(out) > 8100:
        return None
    return out


